package com.cuzorlabs.ashwanitest.data.auth

import com.cuzorlabs.ashwanitest.data.database.DatabaseFactory
import com.cuzorlabs.ashwanitest.domain.auth.model.*
import com.cuzorlabs.ashwanitest.domain.auth.port.*
import java.security.MessageDigest
import java.sql.ResultSet
import java.time.Duration
import java.time.Instant
import java.util.Base64
import java.util.UUID

/** SQLite-backed authentication ports. The name identifies the persistence adapter; it deliberately exposes no credential values. */
class ExposedAuthenticationStore(private val database: DatabaseFactory, private val settings: AuthenticationSettings) : UserStore, SessionStore, LoginThrottleStore, AuthenticationAuditStore, TransactionRunner {
    private val lock = Any()
    override fun <T> inTransaction(action: () -> T): T = synchronized(lock) { action() }
    override fun findByEmail(email: EmailAddress): User? = queryOne("SELECT * FROM users WHERE email = ?", email.value, mapper = ::user)
    override fun findById(id: UserId): User? = queryOne("SELECT * FROM users WHERE id = ?", id.toString(), mapper = ::user)
    override fun create(user: User): User { database.connection().use { c -> c.prepareStatement("INSERT INTO users VALUES(?,?,?,?,?,?,?,?,?,?)").use { s -> bindUser(s, user); s.executeUpdate() } }; return user }
    override fun updatePassword(id: UserId, verifier: PasswordVerifier, mustChangePassword: Boolean, updatedAt: Instant) { database.connection().use { c -> c.prepareStatement("UPDATE users SET verifier_algorithm=?, verifier_work_factor=?, verifier_salt=?, verifier_digest=?, must_change_password=?, updated_at=? WHERE id=?").use { s -> s.setString(1, verifier.algorithm); s.setInt(2, verifier.workFactor); s.setBytes(3, verifier.salt); s.setBytes(4, verifier.digest); s.setInt(5, bool(mustChangePassword)); s.setString(6, updatedAt.toString()); s.setString(7, id.toString()); s.executeUpdate() } } }
    override fun ensurePermanentAdministrator(user: User): User = synchronized(lock) { val existing = findByEmail(user.email); if (existing == null) create(user) else { database.connection().use { c -> c.prepareStatement("UPDATE users SET is_administrator=1 WHERE id=?").use { s -> s.setString(1, existing.id.toString()); s.executeUpdate() } }; requireNotNull(findById(existing.id)) } }
    override fun list(): List<UserSummary> = database.connection().use { c -> c.prepareStatement("SELECT id,email,is_administrator,must_change_password FROM users ORDER BY email").use { s -> s.executeQuery().use { r -> buildList { while (r.next()) add(UserSummary(UserId(UUID.fromString(r.getString(1))), requireNotNull(EmailAddress.parse(r.getString(2))), r.getInt(3) != 0, r.getInt(4) != 0)) } } } }
    override fun issue(token: SessionToken, csrfToken: String, user: AuthenticatedUser, issuedAt: Instant) { database.connection().use { c -> c.prepareStatement("INSERT INTO auth_sessions VALUES(?,?,?,?,?,NULL)").use { s -> s.setString(1, digest(token.value)); s.setString(2, user.id.toString()); s.setString(3, digest(csrfToken)); s.setString(4, issuedAt.toString()); s.setString(5, issuedAt.toString()); s.executeUpdate() } } }
    override fun resolve(token: SessionToken, now: Instant): AuthenticatedUser? = synchronized(lock) { database.connection().use { c -> c.prepareStatement("SELECT s.last_seen_at,s.revoked_at,u.* FROM auth_sessions s JOIN users u ON u.id=s.user_id WHERE s.token_digest=?").use { s -> s.setString(1, digest(token.value)); s.executeQuery().use { r -> if (!r.next() || r.getString("revoked_at") != null || Duration.between(Instant.parse(r.getString("last_seen_at")), now) > settings.inactivityTimeout) null else { val result = user(r); c.prepareStatement("UPDATE auth_sessions SET last_seen_at=? WHERE token_digest=?").use { update -> update.setString(1, now.toString()); update.setString(2, digest(token.value)); update.executeUpdate() }; AuthenticatedUser(result.id, result.email, result.isAdministrator, result.mustChangePassword) } } } } }
    override fun csrfMatches(token: SessionToken, csrfToken: String): Boolean = queryOne("SELECT csrf_digest FROM auth_sessions WHERE token_digest=? AND revoked_at IS NULL", digest(token.value)) { MessageDigest.isEqual(it.getString(1).toByteArray(), digest(csrfToken).toByteArray()) } ?: false
    override fun revoke(token: SessionToken, now: Instant) { execute("UPDATE auth_sessions SET revoked_at=? WHERE token_digest=?", now.toString(), digest(token.value)) }
    override fun revokeUser(id: UserId, now: Instant) { execute("UPDATE auth_sessions SET revoked_at=? WHERE user_id=? AND revoked_at IS NULL", now.toString(), id.toString()) }
    override fun isBlocked(userKey: String?, sourceKey: String, now: Instant): Boolean = listOfNotNull(userKey?.let { blocked("USER", it, now) }, blocked("SOURCE", sourceKey, now)).any { it }
    override fun failed(userKey: String?, sourceKey: String, now: Instant): ThrottleResult = synchronized(lock) { val results = listOfNotNull(userKey?.let { increment("USER", it, now) }, increment("SOURCE", sourceKey, now)); if (results.any { it == ThrottleResult.BLOCK_STARTED }) ThrottleResult.BLOCK_STARTED else if (results.any { it == ThrottleResult.BLOCKED }) ThrottleResult.BLOCKED else ThrottleResult.ALLOWED }
    override fun succeeded(userKey: String?, sourceKey: String) { userKey?.let { execute("DELETE FROM login_throttles WHERE scope=? AND subject=?", "USER", it) }; execute("DELETE FROM login_throttles WHERE scope=? AND subject=?", "SOURCE", sourceKey) }
    override fun append(event: AuthenticationAuditEvent) { database.connection().use { c -> c.prepareStatement("INSERT INTO auth_audit_events VALUES(?,?,?,?,?,?)").use { s -> s.setString(1, UUID.randomUUID().toString()); s.setString(2, event.type.name); s.setString(3, event.occurredAt.toString()); s.setString(4, event.actorId?.toString()); s.setString(5, event.subjectId?.toString()); s.setString(6, event.sourceFingerprint); s.executeUpdate() } } }
    override fun list(limit: Int, offset: Int): List<AuthenticationAuditEvent> = database.connection().use { c -> c.prepareStatement("SELECT event_type,occurred_at,actor_id,subject_id,source_fingerprint FROM auth_audit_events ORDER BY occurred_at DESC LIMIT ? OFFSET ?").use { s -> s.setInt(1, limit); s.setInt(2, offset); s.executeQuery().use { r -> buildList { while (r.next()) add(AuthenticationAuditEvent(AuditEventType.valueOf(r.getString(1)), Instant.parse(r.getString(2)), r.getString(3)?.let { UserId(UUID.fromString(it)) }, r.getString(4)?.let { UserId(UUID.fromString(it)) }, r.getString(5))) } } } }
    override fun purgeBefore(instant: Instant) { execute("DELETE FROM auth_audit_events WHERE occurred_at < ?", instant.toString()) }
    private fun increment(scope: String, subject: String, now: Instant): ThrottleResult { val row = queryOne("SELECT window_started_at,failure_count,block_until FROM login_throttles WHERE scope=? AND subject=?", scope, subject) { Triple(Instant.parse(it.getString(1)), it.getInt(2), it.getString(3)?.let(Instant::parse)) }; if (row?.third?.isAfter(now) == true) return ThrottleResult.BLOCKED; val count = if (row == null || Duration.between(row.first, now) > settings.blockDuration) 1 else row.second + 1; val until = if (count >= settings.failedAttemptLimit) now.plus(settings.blockDuration) else null; database.connection().use { c -> c.prepareStatement("INSERT OR REPLACE INTO login_throttles VALUES(?,?,?,?,?)").use { s -> s.setString(1, scope); s.setString(2, subject); s.setString(3, now.toString()); s.setInt(4, count); s.setString(5, until?.toString()); s.executeUpdate() } }; return if (until != null) ThrottleResult.BLOCK_STARTED else ThrottleResult.ALLOWED }
    private fun blocked(scope: String, subject: String, now: Instant): Boolean = queryOne("SELECT block_until FROM login_throttles WHERE scope=? AND subject=?", scope, subject) { it.getString(1)?.let(Instant::parse)?.isAfter(now) ?: false } ?: false
    private fun execute(sql: String, vararg values: String) { database.connection().use { c -> c.prepareStatement(sql).use { s -> values.forEachIndexed { index, value -> s.setString(index + 1, value) }; s.executeUpdate() } } }
    private fun <T> queryOne(sql: String, vararg values: String, mapper: (ResultSet) -> T): T? = database.connection().use { c -> c.prepareStatement(sql).use { s -> values.forEachIndexed { index, value -> s.setString(index + 1, value) }; s.executeQuery().use { r -> if (r.next()) mapper(r) else null } } }
    private fun user(r: ResultSet) = User(UserId(UUID.fromString(r.getString("id"))), requireNotNull(EmailAddress.parse(r.getString("email"))), PasswordVerifier(r.getString("verifier_algorithm"), r.getInt("verifier_work_factor"), r.getBytes("verifier_salt"), r.getBytes("verifier_digest")), r.getInt("is_administrator") != 0, r.getInt("must_change_password") != 0, Instant.parse(r.getString("created_at")), Instant.parse(r.getString("updated_at")))
    private fun bindUser(s: java.sql.PreparedStatement, user: User) { s.setString(1, user.id.toString()); s.setString(2, user.email.value); s.setString(3, user.verifier.algorithm); s.setInt(4, user.verifier.workFactor); s.setBytes(5, user.verifier.salt); s.setBytes(6, user.verifier.digest); s.setInt(7, bool(user.isAdministrator)); s.setInt(8, bool(user.mustChangePassword)); s.setString(9, user.createdAt.toString()); s.setString(10, user.updatedAt.toString()) }
    private fun bool(value: Boolean) = if (value) 1 else 0
    private fun digest(value: String): String = Base64.getEncoder().encodeToString(MessageDigest.getInstance("SHA-256").digest(value.toByteArray()))
}
